package com.casystem.onboarding.controller;
import com.casystem.onboarding.model.User;import com.casystem.onboarding.repository.UserRepository;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class AccountControllerTest{@Mock UserRepository users;@Mock TokenService tokens;@Mock PasswordEncoder enc;@Mock AuditService audit;@Mock HttpServletRequest req;AccountController c;User u;@BeforeEach void init(){MockitoAnnotations.openMocks(this);c=new AccountController(users,tokens,enc,audit);u=new User();u.setId(2L);u.setName("Ana");u.setPassword("hash");when(tokens.userId(anyString())).thenReturn(2L);when(users.findById(2L)).thenReturn(Optional.of(u));when(req.getRemoteAddr()).thenReturn("ip");}
@Test void cambiaNombre(){var r=c.name("h",Map.of("name","Ana López"),req);assertEquals("Ana López",r.get("name"));verify(users).save(u);}@Test void nombreInvalido(){assertThrows(IllegalArgumentException.class,()->c.name("h",Map.of("name","1"),req));}
@Test void cambiaPassword(){when(enc.matches("Old1234","hash")).thenReturn(true);when(enc.encode("Nueva1234")).thenReturn("nuevo");assertEquals("Contraseña actualizada",c.password("h",Map.of("currentPassword","Old1234","newPassword","Nueva1234"),req).get("message"));assertEquals("nuevo",u.getPassword());}
@Test void passwordActualIncorrectaYNuevaDebil(){when(enc.matches(anyString(),eq("hash"))).thenReturn(false);assertThrows(IllegalArgumentException.class,()->c.password("h",Map.of("currentPassword","mal","newPassword","Nueva1234"),req));when(enc.matches(anyString(),eq("hash"))).thenReturn(true);assertThrows(IllegalArgumentException.class,()->c.password("h",Map.of("currentPassword","ok","newPassword","abc"),req));}}
